#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(ggplot2);library(patchwork);library(survival);library(svglite)})
B<-"/data/y01014/diliyaer/BLCA_CAF_project/GDF15_CAF_project/analysis_revisions_20260906";A<-"/data/y01014/diliyaer/BLCA_CAF_project/GDF15_CAF_project/final_analysis_20260907";O<-file.path(A,"Figure7_clinical_prioritization");dir.create(O,recursive=TRUE,showWarnings=FALSE)
tc<-read.csv(file.path(B,"CCDC80_ECM_program_validation/TCGA_program_multivariable_input.csv"));co<-read.csv(file.path(B,"CCDC80_ECM_program_validation/TCGA_program_immune_correlations.csv"));u<-read.csv(file.path(B,"CCDC80_ECM_program_validation/TCGA_program_univariable_Cox.csv"));m<-read.csv(file.path(B,"CCDC80_ECM_program_validation/TCGA_program_multivariable_Cox_adjusted_CAF_stage.csv"));ct<-read.csv(file.path(B,"unified_candidate_comparison/TCGA_continuous_OS_comparison.csv"));ci<-read.csv(file.path(B,"unified_candidate_comparison/IMvigor210_immune_phenotype_comparison.csv"));cand<-read.csv(file.path(A,"candidate_comparison_final.csv"))
T<-theme_classic(base_family="Arial",base_size=10)+theme(plot.title=element_text(face="bold",size=11,hjust=0),plot.subtitle=element_text(size=8,colour="#444"),axis.title=element_text(size=9),axis.text=element_text(size=8),axis.line=element_line(linewidth=.4),axis.ticks=element_line(linewidth=.3),panel.grid.major=element_line(linewidth=.18,colour="#E9E9E9"),panel.grid.minor=element_blank(),legend.position="none",plot.margin=margin(6,10,6,10))
ts<-tc[!is.na(tc$stage),];ts$stage_label<-factor(paste0("Stage ",ts$stage),levels=paste0("Stage ",sort(unique(ts$stage))));sp<-split(ts$program_score,ts$stage_label);st<-do.call(rbind,lapply(sp,function(x)data.frame(med=median(x),lo=quantile(x,.25),hi=quantile(x,.75),n=length(x))));st$stage_label<-factor(rownames(st),levels=rev(rownames(st)));st$lab<-paste0("n=",st$n,"; median=",sprintf("%.2f",st$med));pA<-ggplot(st,aes(med,stage_label))+geom_vline(xintercept=0,colour="#999",linewidth=.35)+geom_segment(aes(x=lo,xend=hi,y=stage_label,yend=stage_label),linewidth=1.1,colour="#356A8A")+geom_point(size=3,colour="#356A8A")+geom_text(aes(x=hi,label=lab),hjust=-.05,vjust=-.55,size=3)+scale_x_continuous(expand=expansion(mult=c(.04,.28)))+labs(title="(A) Program score across clinical stage",subtitle="TCGA BLCA; samples with missing stage excluded",x="Program score (median and IQR)",y=NULL)+T
co$metric<-factor(co$variable,levels=c("caf_score","myeloid_score","cytotoxicity"),labels=c("CAF score","Myeloid score","Cytotoxicity"));pB<-ggplot(co,aes(metric,1,fill=rho))+geom_tile(width=.9,height=.55)+geom_text(aes(label=sprintf("%.2f",rho)),size=3,colour="white",fontface="bold")+scale_fill_gradient(low="#B8CBD4",high="#356A8A",limits=c(0,.85))+scale_y_continuous(breaks=NULL)+labs(title="(B) Program links to the tumor microenvironment",subtitle="TCGA; Spearman rho, n = 431",x=NULL,y=NULL,fill="rho")+T+theme(legend.position="right")
tc$group<-ifelse(tc$program_score>=median(tc$program_score),"High","Low");sf<-survfit(Surv(time,event)~group,data=tc);z<-summary(sf);km<-data.frame(time=z$time,surv=z$surv,strata=sub("group=","",z$strata));pC<-ggplot(km,aes(time,surv,colour=strata))+geom_step(linewidth=.8)+scale_colour_manual(values=c(High="#A34B45",Low="#356A8A"))+scale_y_continuous(limits=c(0,1),labels=function(x)paste0(x*100,"%"))+labs(title="(C) Program-defined survival stratification",subtitle=paste0("Median split; HR = ",sprintf("%.2f",u$HR),"; P = ",formatC(u$p,format="f",digits=4)),x="Time (days)",y="Overall survival")+T+theme(legend.position=c(.82,.85),legend.title=element_blank())
fm<-rbind(data.frame(term="Program (univariable)",HR=u$HR,lo=u$lo,hi=u$hi,p=u$p),data.frame(term="Program (CAF + stage adjusted)",HR=m$HR[m$term=="program"],lo=m$lo[m$term=="program"],hi=m$hi[m$term=="program"],p=m$p[m$term=="program"]),data.frame(term="CAF score (adjusted)",HR=m$HR[m$term=="caf_score"],lo=m$lo[m$term=="caf_score"],hi=m$hi[m$term=="caf_score"],p=m$p[m$term=="caf_score"]),data.frame(term="Stage (adjusted)",HR=m$HR[m$term=="stage"],lo=m$lo[m$term=="stage"],hi=m$hi[m$term=="stage"],p=m$p[m$term=="stage"]));fm$term<-factor(fm$term,levels=rev(fm$term));pD<-ggplot(fm,aes(HR,term))+geom_vline(xintercept=1,colour="#777",linewidth=.35)+geom_segment(aes(x=lo,xend=hi,y=term,yend=term),linewidth=.7,colour="#356A8A")+geom_point(size=2.5,colour="#356A8A")+scale_x_log10()+labs(title="(D) Program effect is not independent of stage",subtitle="Cox models; points are hazard ratios with 95% CI",x="Hazard ratio (log scale)",y=NULL)+T
ct$source<-"TCGA";ci$source<-"IMvigor210";genes<-intersect(ct$gene,ci$gene);hm<-merge(ct[ct$gene%in%genes,c("gene","FDR")],ci[ci$gene%in%genes,c("gene","FDR")],by="gene",suffixes=c("_TCGA","_IMvigor"));H<-rbind(data.frame(gene=hm$gene,validation="TCGA OS",value=-log10(hm$FDR_TCGA)),data.frame(gene=hm$gene,validation="IMvigor immune",value=-log10(hm$FDR_IMvigor)));H$gene<-factor(H$gene,levels=rev(genes));pE<-ggplot(H,aes(validation,gene,fill=value))+geom_tile(colour="white",linewidth=.7)+geom_text(aes(label=sprintf("%.1f",value)),size=2.8)+scale_fill_gradient(low="#EEF2F3",high="#356A8A")+labs(title="(E) Candidate-level validation matrix",subtitle="Displayed values are -log10 FDR; higher means stronger evidence",x=NULL,y=NULL,fill="-log10 FDR")+T+theme(legend.position="right")
ct$clinical_score<- -log10(ct$FDR);ci2<-ci[match(ct$gene,ci$gene),];ct$immune_score<- -log10(ci2$FDR);fd<-rbind(data.frame(gene=ct$gene,evidence="TCGA OS",score=ct$clinical_score),data.frame(gene=ct$gene,evidence="IMvigor immune",score=ct$immune_score));fd$gene<-factor(fd$gene,levels=rev(unique(fd$gene)));pF<-ggplot(fd,aes(score,gene,fill=evidence))+geom_col(position=position_dodge(width=.72),width=.62)+geom_text(aes(label=sprintf("%.1f",score),group=evidence),position=position_dodge(width=.72),hjust=-.15,size=2.7)+scale_fill_manual(values=c("TCGA OS"="#356A8A","IMvigor immune"="#C98245"))+scale_x_continuous(expand=expansion(mult=c(0,.18)))+labs(title="(F) Candidate evidence ranking",subtitle="Direct values: -log10 FDR",x="-log10 FDR",y=NULL,fill=NULL)+T+theme(legend.position="bottom")
fig<-(pA|pB)/(pC|pD)/(pE|pF)+plot_layout(heights=c(1,1,1));ggsave(file.path(O,"Figure7_clinical_prioritization.pdf"),fig,width=240,height=320,units="mm",device=cairo_pdf,bg="white");ggsave(file.path(O,"Figure7_clinical_prioritization.svg"),fig,width=240,height=320,units="mm",device=svglite,bg="white");ggsave(file.path(O,"Figure7_clinical_prioritization.tif"),fig,width=240,height=320,units="mm",dpi=600,compression="lzw",device="tiff",bg="white")
write.csv(tc,file.path(O,"Figure7_source_TCGA.csv"),row.names=FALSE);write.csv(co,file.path(O,"Figure7_source_correlations.csv"),row.names=FALSE);write.csv(fm,file.path(O,"Figure7_source_Cox.csv"),row.names=FALSE);write.csv(H,file.path(O,"Figure7_source_candidate_matrix.csv"),row.names=FALSE);write.csv(ct,file.path(O,"Figure7_source_candidate_priority.csv"),row.names=FALSE)
